class Solution:
    def filterRestaurants(self, restaurants: List[List[int]], veganFriendly: int, maxPrice: int, maxDistance: int) -> List[int]:
        res = [r for r in restaurants
               if (veganFriendly == 0 or r[2] == 1)
               and r[3] <= maxPrice and r[4] <= maxDistance]
        res.sort(key=lambda r: (-r[1], -r[0]))
        return [r[0] for r in res]

c.cpp:
class Solution {
public:
    vector<int> filterRestaurants(vector<vector<int>>& restaurants, int veganFriendly, int maxPrice, int maxDistance) {
        vector<vector<int>> res;
        for (auto& r : restaurants) {
            if ((veganFriendly == 0 || r[2] == 1) && r[3] <= maxPrice && r[4] <= maxDistance)
                res.push_back(r);
        }
        sort(res.begin(), res.end(), [](const vector<int>& a, const vector<int>& b) {
            if (a[1] != b[1]) return a[1] > b[1];
            return a[0] > b[0];
        });
        vector<int> ids;
        ids.reserve(res.size());
        for (auto& r : res) ids.push_back(r[0]);
        return ids;
    }
};

